export function mountFluidButtons(root=document){const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');let frame=null,target=null,x=50,y=50;const find=e=>e.target.closest?.('.quick-submit:not(:disabled)');function move(e){const el=find(e);if(!el||reduced.matches)return;const r=el.getBoundingClientRect();target=el;x=(e.clientX-r.left)/r.width*100;y=(e.clientY-r.top)/r.height*100;if(frame!==null)return;frame=requestAnimationFrame(()=>{frame=null;if(!target?.isConnected)return;target.style.setProperty('--fluid-x',x+'%');target.style.setProperty('--fluid-y',y+'%')})}function down(e){const el=find(e);if(!el||reduced.matches)return;move(e);const r=el.getBoundingClientRect(),wave=document.createElement('span');wave.className='fluid-click-wave';wave.style.left=(e.clientX-r.left)+'px';wave.style.top=(e.clientY-r.top)+'px';wave.setAttribute('aria-hidden','true');el.appendChild(wave);wave.addEventListener('animationend',()=>wave.remove(),{once:true});setTimeout(()=>wave.remove(),900)}root.addEventListener('pointermove',move,{passive:true});root.addEventListener('pointerdown',down,{passive:true});return()=>{root.removeEventListener('pointermove',move);root.removeEventListener('pointerdown',down);if(frame!==null)cancelAnimationFrame(frame)}}
